-- Change request CR2 (with CR1, CR3), migration 0009: email delivery.
--
-- Additive: three tables and three enums.
--   * email_settings: at most one row; the mail server an administrator
--     configured. No row means delivery is off. The SMTP password is stored
--     only as AES-256-GCM ciphertext; the key (EMAIL_SECRET_KEY) never enters
--     the database.
--   * email_templates: an administrator's wording; a template with no row uses
--     the default in shared/email.ts.
--   * email_deliveries: what the system meant to send and what became of it.
--     Never the message body, which may carry a single-use link.
-- Nothing is seeded and no email is sent by this migration.
--
-- Rollback (loses saved settings, template wording and the delivery log):
--   DROP TABLE email_deliveries; DROP TABLE email_templates; DROP TABLE email_settings;
--   DROP TYPE email_delivery_status; DROP TYPE email_template_key; DROP TYPE email_security;
--   DELETE FROM drizzle.__drizzle_migrations
--     WHERE created_at = (SELECT max(created_at) FROM drizzle.__drizzle_migrations);

CREATE TYPE "public"."email_delivery_status" AS ENUM('queued', 'sent', 'failed', 'suppressed');
CREATE TYPE "public"."email_security" AS ENUM('none', 'starttls', 'tls');
CREATE TYPE "public"."email_template_key" AS ENUM('invitation', 'password_reset', 'password_changed', 'follow_up_due_today', 'follow_up_overdue', 'tender_deadline', 'ownership_changed');
CREATE TABLE "email_deliveries" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"template_key" text NOT NULL,
	"recipient_user_id" uuid,
	"recipient_address" text,
	"status" "email_delivery_status" DEFAULT 'queued' NOT NULL,
	"status_detail" text,
	"attempts" integer DEFAULT 0 NOT NULL,
	"dedupe_key" text,
	"context" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"sent_at" timestamp with time zone,
	CONSTRAINT "email_deliveries_has_recipient" CHECK ("email_deliveries"."recipient_user_id" IS NOT NULL OR "email_deliveries"."recipient_address" IS NOT NULL),
	CONSTRAINT "email_deliveries_sent_has_time" CHECK (("email_deliveries"."status" = 'sent') = ("email_deliveries"."sent_at" IS NOT NULL))
);

CREATE TABLE "email_settings" (
	"id" integer PRIMARY KEY DEFAULT 1 NOT NULL,
	"enabled" boolean DEFAULT false NOT NULL,
	"host" text,
	"port" integer,
	"security" "email_security" DEFAULT 'starttls' NOT NULL,
	"username" text,
	"password_ciphertext" text,
	"from_name" text,
	"from_address" text,
	"reply_to" text,
	"updated_by" uuid,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "email_settings_single_row" CHECK ("email_settings"."id" = 1),
	CONSTRAINT "email_settings_port_range" CHECK ("email_settings"."port" IS NULL OR "email_settings"."port" BETWEEN 1 AND 65535),
	CONSTRAINT "email_settings_enabled_complete" CHECK (NOT "email_settings"."enabled" OR ("email_settings"."host" IS NOT NULL AND "email_settings"."port" IS NOT NULL AND "email_settings"."from_address" IS NOT NULL))
);

CREATE TABLE "email_templates" (
	"key" "email_template_key" PRIMARY KEY NOT NULL,
	"subject" text NOT NULL,
	"body_text" text NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"updated_by" uuid,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "email_templates_subject_length" CHECK (char_length("email_templates"."subject") BETWEEN 1 AND 200),
	CONSTRAINT "email_templates_subject_single_line" CHECK (position(chr(10) in "email_templates"."subject") = 0 AND position(chr(13) in "email_templates"."subject") = 0),
	CONSTRAINT "email_templates_body_length" CHECK (char_length("email_templates"."body_text") BETWEEN 1 AND 10000)
);

ALTER TABLE "email_deliveries" ADD CONSTRAINT "email_deliveries_recipient_user_id_users_id_fk" FOREIGN KEY ("recipient_user_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "email_deliveries" ADD CONSTRAINT "email_deliveries_created_by_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "email_settings" ADD CONSTRAINT "email_settings_updated_by_users_id_fk" FOREIGN KEY ("updated_by") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "email_templates" ADD CONSTRAINT "email_templates_updated_by_users_id_fk" FOREIGN KEY ("updated_by") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;
CREATE UNIQUE INDEX "email_deliveries_dedupe_unique" ON "email_deliveries" USING btree ("dedupe_key");
CREATE INDEX "email_deliveries_created_idx" ON "email_deliveries" USING btree ("created_at");
CREATE INDEX "email_deliveries_status_idx" ON "email_deliveries" USING btree ("status");


-- The runtime role reads and writes these tables but never deletes from them:
-- settings and wording change by update, and the delivery log is history.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'penta_app') THEN
    RAISE NOTICE 'Role penta_app not present; skipping runtime grants.';
    RETURN;
  END IF;
  EXECUTE 'GRANT SELECT, INSERT, UPDATE ON email_settings, email_templates, email_deliveries TO penta_app';
  EXECUTE 'REVOKE DELETE, TRUNCATE ON email_settings, email_templates, email_deliveries FROM penta_app';
END $$;

